[PostHandlerFor(classStr(LeaveRequestEventHandler), methodStr(LeaveRequestEventHandler, completed))]
public static void LeaveRequestEventHandler_Post_completed(XppPrePostArgs args)
{
    WorkflowEventArgs _workflowEventArgs = args.getArg('_workflowEventArgs');
    if (_workflowEventArgs && _workflowEventArgs.parmWorkflowContext())
    {
        LeaveRequestRecId   leaveRequestRecId   = _workflowEventArgs.parmWorkflowContext().parmRecId();
        LeaveRequest        leaveRequest        = LeaveRequest::find(leaveRequestRecId);

        if(leaveRequest)
        {
            NVTimesheetChangeHandler::insertNewRef(leaveRequest.Worker, leaveRequest.TableId, leaveRequest.RecId);
        }
    }
}
